func wuffs_base__status__is_truncated_input_error(tls *libc.TLS, z uintptr) (r uint8) {
	var p, v1 uintptr
	_, _ = p, v1
	p = (*wuffs_base__status)(unsafe.Pointer(z)).Frepr
	if !(p != 0) || int32(**(**int8)(__ccgo_up(p))) != int32('#') {
		return libc.BoolUint8(false1 != 0)
	}
	p = p + 1
	for int32(1) != 0 {
		if int32(**(**int8)(__ccgo_up(p))) == 0 {
			return libc.BoolUint8(false1 != 0)
		} else {
			v1 = p
			p = p + 1
			if int32(**(**int8)(__ccgo_up(v1))) == int32(':') {
				break
			}
		}
	}
	return libc.BoolUint8(libc.Xstrcmp(tls, p, __ccgo_ts+30) == 0)
}

// C documentation
//
//	// wuffs_base__status__message strips the leading '$', '#' or '@'.
func wuffs_base__status__message(tls *libc.TLS, z uintptr) (r uintptr) {
	if (*wuffs_base__status)(unsafe.Pointer(z)).Frepr != 0 {
		if int32(**(**int8)(__ccgo_up((*wuffs_base__status)(unsafe.Pointer(z)).Frepr))) == int32('$') || int32(**(**int8)(__ccgo_up((*wuffs_base__status)(unsafe.Pointer(z)).Frepr))) == int32('#') || int32(**(**int8)(__ccgo_up((*wuffs_base__status)(unsafe.Pointer(z)).Frepr))) == int32('@') {
			return (*wuffs_base__status)(unsafe.Pointer(z)).Frepr + uintptr(1)
		}
	}
	return (*wuffs_base__status)(unsafe.Pointer(z)).Frepr
}

