// C documentation
//
//	// wuffs_base__color_u32_argb_nonpremul__as__color_u32_argb_premul converts
//	// from non-premultiplied alpha to premultiplied alpha.
func wuffs_base__color_u32_argb_nonpremul__as__color_u32_argb_premul(tls *libc.TLS, argb_nonpremul uint32_t) (r1 wuffs_base__color_u32_argb_premul) {
	var a, a16, b, g, r uint32_t
	_, _, _, _, _ = a, a16, b, g, r
	// Multiplying by 0x101 (twice, once for alpha and once for color) converts
	// from 8-bit to 16-bit color. Shifting right by 8 undoes that.
	//
	// Working in the higher bit depth can produce slightly different (and
	// arguably slightly more accurate) results. For example, given 8-bit blue
	// and alpha of 0x80 and 0x81:
	//
	//  - ((0x80   * 0x81  ) / 0xFF  )      = 0x40        = 0x40
	//  - ((0x8080 * 0x8181) / 0xFFFF) >> 8 = 0x4101 >> 8 = 0x41
	a = uint32(0xFF) & (argb_nonpremul >> libc.Int32FromInt32(24))
	a16 = a * libc.Uint32FromInt32(libc.Int32FromInt32(0x101)*libc.Int32FromInt32(0x101))
	r = uint32(0xFF) & (argb_nonpremul >> libc.Int32FromInt32(16))
	r = r * a16 / uint32(0xFFFF) >> int32(8)
	g = uint32(0xFF) & (argb_nonpremul >> libc.Int32FromInt32(8))
	g = g * a16 / uint32(0xFFFF) >> int32(8)
	b = uint32(0xFF) & (argb_nonpremul >> libc.Int32FromInt32(0))
	b = b * a16 / uint32(0xFFFF) >> int32(8)
	return a<<libc.Int32FromInt32(24) | r<<libc.Int32FromInt32(16) | g<<libc.Int32FromInt32(8) | b<<libc.Int32FromInt32(0)
}

